  struct Traits;
  static const ::flatbuffers::TypeTable *MiniReflectTypeTable() {
    return InputTypeTable();
  }
  enum FlatBuffersVTableOffset FLATBUFFERS_VTABLE_UNDERLYING_TYPE {
    VT_TAG = 4,
    VT_MODE = 6,
    VT_FLAGS = 8,
    VT_OVERRIDEINDEX = 10,
    VT_CONSTANT = 12,
    VT_WALK = 14,
    VT_SELECTED = 16
  };
  /// The type T of the read.
  rigExec::fb::InputTag tag() const {
    return static_cast<rigExec::fb::InputTag>(GetField<uint8_t>(VT_TAG, 0));
  }
  rigExec::fb::ReadMode mode() const {
    return static_cast<rigExec::fb::ReadMode>(GetField<uint8_t>(VT_MODE, 0));
  }
  /// InputReadFlags.
  uint8_t flags() const {
    return GetField<uint8_t>(VT_FLAGS, 0);
  }
  /// Baked: the program's override number (dense from 0), else -1.
  int32_t overrideIndex() const {
    return GetField<int32_t>(VT_OVERRIDEINDEX, -1);
  }
  /// values[]: RigExecBakedInput::constant in Baked mode (the bind fallback
  /// of a varying read, the folded value of a constant one); the site's
  /// fallback in the other modes.
  uint32_t constant() const {
    return GetField<uint32_t>(VT_CONSTANT, 0);
  }
  /// Slot ids, head first.
  const ::flatbuffers::Vector<uint32_t> *walk() const {
    return GetPointer<const ::flatbuffers::Vector<uint32_t> *>(VT_WALK);
  }
  /// Baked, Varying and not LongWay: index into `walk` of the attribute the
  /// program's query is pinned to; -1 otherwise.
  int16_t selected() const {
    return GetField<int16_t>(VT_SELECTED, -1);
  }
  template <bool B = false>
  bool Verify(::flatbuffers::VerifierTemplate<B> &verifier) const {
    return VerifyTableStart(verifier) &&
           VerifyField<uint8_t>(verifier, VT_TAG, 1) &&
           VerifyField<uint8_t>(verifier, VT_MODE, 1) &&
           VerifyField<uint8_t>(verifier, VT_FLAGS, 1) &&
           VerifyField<int32_t>(verifier, VT_OVERRIDEINDEX, 4) &&
           VerifyField<uint32_t>(verifier, VT_CONSTANT, 4) &&
           VerifyOffset(verifier, VT_WALK) &&
           verifier.VerifyVector(walk()) &&
           VerifyField<int16_t>(verifier, VT_SELECTED, 2) &&
           verifier.EndTable();
  }
  RigExecWireInput *UnPack(const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
