inline ::flatbuffers::Offset<Step> CreateStep(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    rigExec::fb::StepKind kind = rigExec::fb::StepKind::ComposeSubtree,
    int32_t object = -1,
    int32_t part = -1,
    ::flatbuffers::Offset<::flatbuffers::Vector<const rigExec::fb::SlotRange *>> reads = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<const rigExec::fb::SlotRange *>> writes = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<int32_t>> preds = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<int32_t>> succs = 0,
    bool isSource = false,
    bool externalReads = false,
    bool varyingInputs = false,
    bool resolvedInputReads = false,
    ::flatbuffers::Offset<::flatbuffers::Vector<int32_t>> overrideInputs = 0,
    int32_t cluster = -1,
    int32_t level = 0,
    const rigExec::fb::F64 *sizeUnits = nullptr,
    const rigExec::fb::F64 *cost = nullptr,
    uint32_t maxDiagnostics = 0) {
  StepBuilder builder_(_fbb);
  builder_.add_maxDiagnostics(maxDiagnostics);
  builder_.add_cost(cost);
  builder_.add_sizeUnits(sizeUnits);
  builder_.add_level(level);
  builder_.add_cluster(cluster);
  builder_.add_overrideInputs(overrideInputs);
  builder_.add_succs(succs);
  builder_.add_preds(preds);
  builder_.add_writes(writes);
  builder_.add_reads(reads);
  builder_.add_part(part);
  builder_.add_object(object);
  builder_.add_resolvedInputReads(resolvedInputReads);
  builder_.add_varyingInputs(varyingInputs);
  builder_.add_externalReads(externalReads);
  builder_.add_isSource(isSource);
  builder_.add_kind(kind);
  return builder_.Finish();
}

