inline ::flatbuffers::Offset<Rbf> CreateRbf(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::Vector<const rigExec::fb::Vec3d *>> poses = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<const rigExec::fb::Vec3d *>> translations = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint8_t>> poseTypes = 0,
    const rigExec::fb::Vec3d *twistAxis = nullptr,
    uint8_t kernel = 0,
    const rigExec::fb::F64 *radius = nullptr,
    const rigExec::fb::F64 *translationRadius = nullptr,
    ::flatbuffers::Offset<::flatbuffers::Vector<double>> radii = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<double>> translationRadii = 0,
    const rigExec::fb::F64 *regularization = nullptr,
    bool normalize = true,
    bool enableRotation = true,
    bool enableTranslation = false,
    bool regularizedSingular = false,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<rigExec::fb::DoubleList>>> weights = 0) {
  RbfBuilder builder_(_fbb);
  builder_.add_weights(weights);
  builder_.add_regularization(regularization);
  builder_.add_translationRadii(translationRadii);
  builder_.add_radii(radii);
  builder_.add_translationRadius(translationRadius);
  builder_.add_radius(radius);
  builder_.add_twistAxis(twistAxis);
  builder_.add_poseTypes(poseTypes);
  builder_.add_translations(translations);
  builder_.add_poses(poses);
  builder_.add_regularizedSingular(regularizedSingular);
  builder_.add_enableTranslation(enableTranslation);
  builder_.add_enableRotation(enableRotation);
  builder_.add_normalize(normalize);
  builder_.add_kernel(kernel);
  return builder_.Finish();
}

