struct ChainBuilder {
  typedef Chain Table;
  ::flatbuffers::FlatBufferBuilder &fbb_;
  ::flatbuffers::uoffset_t start_;
  void add_target(uint32_t target) {
    fbb_.AddElement<uint32_t>(Chain::VT_TARGET, target, 0);
  }
  void add_revisions(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<rigExec::fb::Revision>>> revisions) {
    fbb_.AddOffset(Chain::VT_REVISIONS, revisions);
  }
  void add_derived(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<rigExec::fb::Derived>>> derived) {
    fbb_.AddOffset(Chain::VT_DERIVED, derived);
  }
  void add_haveBase(bool haveBase) {
    fbb_.AddElement<uint8_t>(Chain::VT_HAVEBASE, static_cast<uint8_t>(haveBase), 0);
  }
  void add_base(uint32_t base) {
    fbb_.AddElement<uint32_t>(Chain::VT_BASE, base, 0);
  }
  explicit ChainBuilder(::flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  ::flatbuffers::Offset<Chain> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = ::flatbuffers::Offset<Chain>(end);
    return o;
  }
};

inline ::flatbuffers::Offset<Chain> CreateChain(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    uint32_t target = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<rigExec::fb::Revision>>> revisions = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<rigExec::fb::Derived>>> derived = 0,
    bool haveBase = false,
    uint32_t base = 0) {
  ChainBuilder builder_(_fbb);
  builder_.add_base(base);
  builder_.add_derived(derived);
  builder_.add_revisions(revisions);
  builder_.add_target(target);
  builder_.add_haveBase(haveBase);
  return builder_.Finish();
}

struct Chain::Traits {
  using type = Chain;
  static auto constexpr Create = CreateChain;
};

inline ::flatbuffers::Offset<Chain> CreateChainDirect(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    uint32_t target = 0,
    const std::vector<::flatbuffers::Offset<rigExec::fb::Revision>> *revisions = nullptr,
    const std::vector<::flatbuffers::Offset<rigExec::fb::Derived>> *derived = nullptr,
    bool haveBase = false,
    uint32_t base = 0) {
  auto revisions__ = revisions ? _fbb.CreateVector<::flatbuffers::Offset<rigExec::fb::Revision>>(*revisions) : 0;
  auto derived__ = derived ? _fbb.CreateVector<::flatbuffers::Offset<rigExec::fb::Derived>>(*derived) : 0;
  return rigExec::fb::CreateChain(
      _fbb,
      target,
      revisions__,
      derived__,
      haveBase,
      base);
}

::flatbuffers::Offset<Chain> CreateChain(::flatbuffers::FlatBufferBuilder &_fbb, const RigExecWireChain *_o, const ::flatbuffers::rehasher_function_t *_rehasher = nullptr);

